import{_ as t,o as n,c as o,ak as s}from"./chunks/framework.sV-XtlWr.js";const w=JSON.parse('{"title":"Editor connection","description":"Connect the Piwi extension for VS Code or the JetBrains plugin to your instance: the connection the reporter already uses, a browser sign-in that creates an API key for the editor, or the desktop app running on your machine, beside a shared instance.","frontmatter":{"title":"Editor connection","description":"Connect the Piwi extension for VS Code or the JetBrains plugin to your instance: the connection the reporter already uses, a browser sign-in that creates an API key for the editor, or the desktop app running on your machine, beside a shared instance.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-connection.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-connection.html"}],["meta",{"property":"og:title","content":"Editor connection | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Connect the Piwi extension for VS Code or the JetBrains plugin to your instance: the connection the reporter already uses, a browser sign-in that creates an API key for the editor, or the desktop app running on your machine, beside a shared instance."}]]},"headers":[],"relativePath":"features/editor-connection.md","filePath":"features/editor-connection.md","lastUpdated":1791026401000}'),i={name:"features/editor-connection.md"};function a(r,e,h,c,d,p){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="editor-connection" tabindex="-1">Editor connection <a class="header-anchor" href="#editor-connection" aria-label="Permalink to &quot;Editor connection&quot;">​</a></h1><p>The <a href="./editors.html">editor extensions</a> read everything from your Piwi instance. They find it in this order, and the first that names an instance wins:</p><ol><li>the <a href="/features/desktop.html">desktop app</a>, while it runs, when you chose it with <strong>Piwi: Connect</strong> on this machine;</li><li><code>PIWI_DASHBOARD_URL</code>, <code>PIWI_API_KEY</code> and <code>PIWI_PROJECT_NAME</code> in the environment the editor was started with;</li><li>the same variables in the <code>.env</code> next to the Playwright config, then at the repository root (a URL there takes only its own key);</li><li>the instance saved with <strong>Piwi: Connect</strong>;</li><li>the desktop app, while it runs.</li></ol><p>A project set up for the reporter needs nothing more. An editor started from the Dock or the Start menu may not see the variables your shell exports: the <code>.env</code> or Connect work either way.</p><h2 id="with-the-desktop-app" tabindex="-1">With the desktop app <a class="header-anchor" href="#with-the-desktop-app" aria-label="Permalink to &quot;With the desktop app&quot;">​</a></h2><p>The desktop app needs no pairing with the editor: while it runs, it publishes its address and a local token in <code>~/.piwi/desktop.json</code>, which the editor reads, as the reporter does. The editor notices within seconds when the app starts or quits. With nothing else naming an instance, the editor uses the app as soon as it runs.</p><h3 id="beside-a-shared-instance" tabindex="-1">Beside a shared instance <a class="header-anchor" href="#beside-a-shared-instance" aria-label="Permalink to &quot;Beside a shared instance&quot;">​</a></h3><p>When the environment, a <code>.env</code> or Connect names your team&#39;s instance, the desktop app sits beside it rather than replacing it. Run <strong>Piwi: Connect</strong>: it lists the desktop app, the instance the workspace names, and <strong>Another instance</strong>, and marks the one in use. Choose <strong>The Piwi desktop app</strong>, and the editor reads the app first while it runs, then the shared instance again when the app quits. Choosing the shared instance in the same list switches back; its address, project and key stay saved throughout.</p><p>The choice is kept on your machine only (VS Code&#39;s workspace state, <code>.idea/workspace.xml</code> in a JetBrains IDE), never in a file the team shares. In a JetBrains IDE, <strong>Settings → Tools → Piwi</strong> shows it too, as <strong>Read this project from the desktop app while it runs</strong>. When the app starts while the editor reads another instance, the editor offers the switch once per workspace.</p><h3 id="the-project" tabindex="-1">The project <a class="header-anchor" href="#the-project" aria-label="Permalink to &quot;The project&quot;">​</a></h3><p>With the app chosen, the project is the one picked with Connect, else the one whose <strong>linked folder</strong> holds the workspace&#39;s Playwright config (link the folder on the project&#39;s page in the desktop app), else <code>PIWI_PROJECT_NAME</code>. When the app is used because nothing else names an instance, <code>PIWI_PROJECT_NAME</code> comes first, since the reporter sends its runs there under that name too.</p><h2 id="connect" tabindex="-1">Connect <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Connect&quot;">​</a></h2><p>Run <strong>Piwi: Connect</strong> from the command palette, or click <strong>Piwi: connect</strong> in the status bar. In a JetBrains IDE it is the <strong>Connect…</strong> button of <strong>Settings → Tools → Piwi</strong>, in the <strong>Piwi</strong> tool window&#39;s toolbar, and under <strong>Tools → Piwi</strong>.</p><ol><li>When the desktop app runs, Connect lists it first, with the instance the workspace already names: choose <strong>The Piwi desktop app</strong>, and pick the project if none is linked to the folder, or choose the instance to switch back to it. Otherwise, or with <strong>Another instance</strong>, give the instance&#39;s address, such as <code>https://piwi.example.com</code>.</li><li>When the instance has a login, choose <strong>Sign in with the browser</strong>. The instance&#39;s page opens with a code: check that the editor shows the same code, then click <strong>Allow</strong>. The editor receives an <a href="/operate/api-keys.html">API key</a> created for you and named after it, such as &quot;Piwi in WebStorm on macOS&quot;, which you can revoke with your other keys. Or paste a key you created yourself. An instance without a login needs no key.</li><li>Pick the project.</li></ol><p>When the environment or a <code>.env</code> names another instance, Connect saves your choice and says which source comes first. In a JetBrains IDE, an instance on your machine is reached at <code>localhost</code>, <code>127.0.0.1</code> or <code>[::1]</code>, whichever it listens on: Connect tries all three and saves the one that answered.</p><h2 id="what-is-saved-where" tabindex="-1">What is saved where <a class="header-anchor" href="#what-is-saved-where" aria-label="Permalink to &quot;What is saved where&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>VS Code</th><th>JetBrains IDEs</th></tr></thead><tbody><tr><td>Address and project</td><td><code>piwi.serverUrl</code> and <code>piwi.project</code> in the workspace settings</td><td><code>.idea/piwi.xml</code></td></tr><tr><td>The desktop app chosen, and its project</td><td>The workspace state, on this machine only</td><td><code>.idea/workspace.xml</code>, on this machine only</td></tr><tr><td>API key</td><td>The editor&#39;s secret storage</td><td>The IDE&#39;s password safe</td></tr></tbody></table><p>The address and the project can be shared with the team. The key never goes to a file, and is saved for its instance only: a repository whose settings name another instance never receives it. <strong>Piwi: Disconnect</strong> (the <strong>Disconnect</strong> button in a JetBrains IDE) forgets the address, the project, that instance&#39;s key and the choice of the desktop app.</p><h2 id="which-connection-is-in-use" tabindex="-1">Which connection is in use <a class="header-anchor" href="#which-connection-is-in-use" aria-label="Permalink to &quot;Which connection is in use&quot;">​</a></h2><p>The status bar&#39;s tooltip names the instance and where it came from, and says when the desktop app runs while another instance is in use, or was chosen and is not running. In a JetBrains IDE, <strong>Settings → Tools → Piwi</strong> and the <strong>Piwi</strong> tool window say the same, or why the editor is not connected. The plugin starts its service when you open a file of a project that holds a Playwright config; until then, both say so, and Connect still finds the desktop app.</p><p><strong>Piwi: Open settings</strong> in VS Code opens the extension&#39;s settings.</p>',21)])])}const u=t(i,[["render",a]]);export{w as __pageData,u as default};
